<template><section class="b-panel"><h2>政府职责分配</h2><p class="b-muted">平台分配入驻审核责任及主办方管理范围，政府岗位只办理被分配的申请和组织。</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-table :data="data?.applications||[]"><el-table-column prop="name" label="待审核主办方"/><el-table-column label="当前审核人"><template #default="{row}">{{reviewerName(row.assigned_reviewer_id)}}</template></el-table-column><el-table-column label="分配责任"><template #default="{row}"><el-select v-model="assignees[row.id]" placeholder="选择政府审核岗位"><el-option v-for="person in data?.reviewers||[]" :key="person.user_id" :label="person.nick_name" :value="person.user_id"/></el-select><el-button link type="primary" :disabled="!assignees[row.id]||busy" @click="assign(row)">确认分配</el-button></template></el-table-column></el-table><h3>主办方管理范围</h3><el-form label-position="top"><el-form-item label="主办方"><el-select v-model="form.organizationId"><el-option v-for="org in data?.organizations||[]" :key="org.id" :label="org.name" :value="org.id"/></el-select></el-form-item><el-form-item label="政府岗位"><el-select v-model="form.sysUserId"><el-option v-for="person in data?.reviewers||[]" :key="person.user_id" :label="person.nick_name" :value="person.user_id"/></el-select></el-form-item><el-form-item label="具体职责"><el-checkbox-group v-model="permissions"><el-checkbox value="qualify">资格暂停与恢复</el-checkbox><el-checkbox value="summary">必要业务汇总</el-checkbox><el-checkbox value="complaint">投诉协调</el-checkbox></el-checkbox-group></el-form-item><el-button type="primary" :loading="busy" :disabled="!form.organizationId||!form.sysUserId||!permissions.length" @click="grant">核对后授权</el-button></el-form><el-table :data="data?.grants||[]"><el-table-column prop="organization_name" label="主办方"/><el-table-column prop="nick_name" label="政府岗位"/><el-table-column label="职责"><template #default="{row}">{{permissionNames(row.permissions)}}</template></el-table-column><el-table-column label="办理"><template #default="{row}"><el-button link type="warning" :disabled="busy" @click="revoke(row)">撤回授权</el-button></template></el-table-column></el-table></section></template>
<script setup lang="ts">
import request from '@/utils/request';import {performAction} from '@/api/sports/phase1';
interface Application {id:string;name:string;version:number;assigned_reviewer_id:string|null}
interface Grant {organization_id:string;sys_user_id:string;permissions:string;organization_name:string;nick_name:string}
interface Administration {applications:Application[];reviewers:{user_id:string;nick_name:string}[];organizations:{id:string;name:string}[];grants:Grant[]}
const data=ref<Administration>();const error=ref('');const busy=ref(false);const assignees=reactive<Record<string,string>>({});const form=reactive({organizationId:'',sysUserId:''});const permissions=ref(['qualify','summary','complaint']);
const labels:Record<string,string>={qualify:'资格管理',summary:'必要汇总',complaint:'投诉协调'};
function permissionNames(value:string){try{return JSON.parse(value).map((p:string)=>labels[p]||p).join('、');}catch{return '请刷新核对';}}
function reviewerName(id:string|null){return data.value?.reviewers.find(p=>p.user_id===id)?.nick_name||'尚未分配';}
async function load(){try{data.value=(await request<Administration>({url:'/sports/government/administration'})).data;error.value='';}catch{error.value='当前账号不能分配责任，请由平台负责人办理。';}}
async function run(code:string,input:Record<string,string|number>,text:string){busy.value=true;try{await performAction(code,input,text);await load();}finally{busy.value=false;}}
async function assign(row:Application){await run('government.assignAdmission',{applicationId:row.id,sysUserId:assignees[row.id],expectedVersion:row.version},`将「${row.name}」交给${reviewerName(assignees[row.id])}审核？`);}
async function grant(){await run('government.grant',{...form,permissions:permissions.value.join(','),status:'active'},'确认授予所选组织和职责范围？其他组织不会自动开放。');}
async function revoke(row:Grant){await run('government.grant',{organizationId:row.organization_id,sysUserId:row.sys_user_id,permissions:JSON.parse(row.permissions).join(','),status:'revoked'},`撤回${row.nick_name}对「${row.organization_name}」的管理范围？`);}
onMounted(load);
</script>
